def create_project(output_dir: str) -> None:
    """Create all project files in the specified directory."""
    print(f"\n\U0001f9fe BillFlow Pro - Project Generator")
    print(f"=" * 50)
    print(f"Output directory: {output_dir}\n")

    os.makedirs(output_dir, exist_ok=True)

    created = 0
    for filepath, content in sorted(FILES.items()):
        full_path = os.path.join(output_dir, filepath)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        created += 1
        print(f"  \u2705 {filepath}")

    # Create .env from .env.example
    env_example = os.path.join(output_dir, ".env.example")
    env_file = os.path.join(output_dir, ".env")
    if os.path.exists(env_example) and not os.path.exists(env_file):
        shutil.copy2(env_example, env_file)
        print(f"  \u2705 .env (copied from .env.example)")
        created += 1

    # Make start.sh executable
    start_sh = os.path.join(output_dir, "backend-fastapi", "start.sh")
    if os.path.exists(start_sh):
        os.chmod(start_sh, 0o755)

    print(f"\n\u2728 Created {created} files successfully!")
    print(f"\n\U0001f680 Next steps:")
    print(f"   cd {output_dir}")
    print(f"   docker-compose up --build")
    print(f"\n   Frontend:  http://localhost:3000")
    print(f"   API Docs:  http://localhost:8000/docs")
    print(f"   Node.js:   http://localhost:3001/health")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generate BillFlow Pro project")
    parser.add_argument(
        "--output-dir",
        default="billflow-pro",
        help="Output directory (default: billflow-pro)"
    )
    args = parser.parse_args()
    create_project(args.output_dir)
